(() => {
  const app=document.querySelector('#app'),mode=document.body.dataset.portal;let session=null,state=null,group=0,dirty=false,saving=false,uploading=false,publishing=false,offset=0,search='',filter='';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rupiah=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
  const date=n=>new Date(n).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
  const svg=(name)=>{const paths={orders:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h3"/>',edit:'<path d="m14 4 6 6M4 20l5-1 12-12-5-5L4 14Z"/>',out:'<path d="M10 4H4v16h6M10 12h11m-4-4 4 4-4 4"/>',save:'<path d="M4 3h14l3 3v15H3V3Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/>',preview:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',publish:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v7h16v-7"/>',wa:'<path d="M12 2.5a9.5 9.5 0 0 0-8.3 14.2L2.5 21.5l4.8-1.2A9.5 9.5 0 1 0 12 2.5Z"/><path d="m8 8 2 3-1 1a10 10 0 0 0 4 4l1-1 3 2"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.orders}</svg>`;};
  function notify(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.classList.toggle('error',error);t.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.hidden=true,error?9500:4000);}
  async function api(path,options={}){const headers={'Accept':'application/json',...(session?{'X-CSRF-Token':session.csrf}:{}),...(options.headers||{})};if(options.body&&typeof options.body!=='string'&&!(options.body instanceof Blob)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}let r;try{r=await fetch(path,{...options,headers,credentials:'same-origin'});}catch{throw new Error('Tidak terhubung. Perubahan belum disimpan; coba lagi.');}let data;try{data=await r.json();}catch{throw new Error('Layanan belum dapat dihubungi. Coba lagi.');}if(!r.ok){const e=new Error(data.error||'Permintaan gagal.');e.status=r.status;throw e;}return data;}
  function sidebar(){return `<aside class="sidebar"><a class="brand" href="/" aria-label="Rasio Agency"><img src="/assets/rasio-logo.png" width="119" height="46" alt="Rasio Agency"></a><div><p class="sidebar-title">${mode==='admin'?'Workspace':'Website Anda'}</p><nav class="sidebar-nav" aria-label="Navigasi workspace"><${mode==='admin'?'a href="/admin"':'button type="button"'} class="active"><span class="icon">${svg(mode==='admin'?'orders':'edit')}</span>${mode==='admin'?'Pesanan':state?.content?'Konten website':'Status pesanan'}</${mode==='admin'?'a':'button'}></nav></div><div class="sidebar-bottom"><a href="/">Buka website Rasio</a><button class="btn" data-logout>${svg('out')} Keluar</button></div></aside>`;}
  function layout(content){app.innerHTML=`<div class="portal-layout">${sidebar()}<div class="main">${content}</div></div>`;document.querySelector('[data-logout]').addEventListener('click',async()=>{if(dirty&&!await confirmAction('Keluar tanpa menyimpan?','Perubahan yang belum disimpan akan hilang.','Keluar'))return;try{await api('/api/logout',{method:'POST'});session=null;dirty=false;login();}catch(e){notify(e.message,true);}});}
  const validOrder=id=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id||'');
  function routeSession(value){if(!value||!['admin','client'].includes(value.role))throw new Error('Akses tidak valid. Silakan masuk kembali.');session=value;if(session.role===mode)return true;const id=new URLSearchParams(location.search).get('order');const target=session.role==='admin'?'/admin'+(validOrder(id)?'?order='+encodeURIComponent(id):''):'/cms';location.replace(target);return false;}
  function login(error=''){app.innerHTML=`<div class="login-page"><form class="login-card card"><a class="brand" href="/"><img src="/assets/rasio-logo.png" width="119" height="46" alt="Rasio Agency"></a><h1>${mode==='admin'?'Masuk ke admin Rasio':'Kelola website Anda'}</h1><p>${mode==='admin'?'Gunakan kode akses admin Anda.':'Masukkan kode akses yang diberikan tim Rasio.'}</p><label for="access-code">Kode akses</label><input id="access-code" type="password" autocomplete="off" spellcheck="false" required><button class="btn primary" type="submit">Masuk</button><a class="back" href="/">Kembali ke Rasio Agency</a></form></div>`;app.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const s=await api('/api/access',{method:'POST',body:{code:document.querySelector('#access-code').value.trim()}});if(!routeSession(s))return;await load();}catch(e){notify(e.message,true);button.disabled=false;}});if(error)notify(error,true);}
  async function confirmAction(title,text,label='Lanjutkan'){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="actions"><button class="btn" data-cancel>Batal</button><button class="btn primary" data-confirm>${esc(label)}</button></div>`;document.body.append(d);d.addEventListener('cancel',()=>{d.remove();resolve(false);});d.querySelector('[data-cancel]').onclick=()=>{d.close();d.remove();resolve(false);};d.querySelector('[data-confirm]').onclick=()=>{d.close();d.remove();resolve(true);};d.showModal();});}
  function statusPill(o){return `<span class="pill ${o.status==='active'?'active':o.status==='cancelled'?'cancelled':o.status==='new'?'pending':''}">${esc(o.statusLabel)}</span>`;}
  async function list(){state=null;const result=await api(`/api/admin/orders?q=${encodeURIComponent(search)}&status=${filter}&offset=${offset}`);const n=result.stats;layout(`<div class="topline"><div><h1>Pesanan website</h1><p class="muted">Kelola pesanan Rasio Profile dan proses aktivasi.</p></div><a class="btn" href="/order?type=profile">Buka pemesanan</a></div><div class="stats">${[['Total pesanan',n.total],['Pesanan baru',n.new],['Menunggu pembayaran',n.pending],['Website aktif',n.active]].map(([label,num])=>`<div class="stat card"><span>${label}</span><strong>${num||0}</strong></div>`).join('')}</div><section class="card"><form class="filters"><input aria-label="Cari pesanan" placeholder="Cari nama bisnis atau nomor pesanan" value="${esc(search)}"><select aria-label="Filter status"><option value="">Semua status</option>${[['new','Pesanan baru'],['materials','Menunggu materi'],['building','Sedang disiapkan'],['review','Siap ditinjau'],['active','Website aktif'],['cancelled','Dibatalkan']].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select><button class="btn" type="submit">Cari</button></form>${result.orders.length?`<div class="table-wrap"><table><thead><tr><th>Bisnis</th><th>Paket</th><th>Status</th><th>Pembayaran</th><th></th></tr></thead><tbody>${result.orders.map(o=>`<tr><td><strong>${esc(o.businessName)}</strong><small>${esc(o.reference)}</small></td><td>${o.duration} bulan<small>${rupiah(o.total)}</small></td><td>${statusPill(o)}</td><td><span class="pill ${o.paymentStatus==='verified'?'active':'pending'}">${o.paymentStatus==='verified'?'Terverifikasi':'Menunggu'}</span></td><td><a class="btn" href="/admin?order=${o.id}">Kelola</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><span class="icon">${svg('orders')}</span><h2>${search||filter?'Tidak ada hasil':'Belum ada pesanan'}</h2><p>${search||filter?'Coba nama bisnis atau status lain.':'Pesanan baru akan muncul di sini setelah pelanggan mengirim pemesanan.'}</p></div>`}${offset||result.hasMore?`<div class="paging"><button class="btn" data-page-prev ${!offset?'disabled':''}>Sebelumnya</button><button class="btn" data-page-next ${!result.hasMore?'disabled':''}>Selanjutnya</button></div>`:''}</section>`);app.querySelector('.filters').onsubmit=e=>{e.preventDefault();search=e.target.querySelector('input').value;filter=e.target.querySelector('select').value;offset=0;list().catch(e=>notify(e.message,true));};app.querySelector('[data-page-prev]')?.addEventListener('click',()=>{offset=Math.max(0,offset-50);list();});app.querySelector('[data-page-next]')?.addEventListener('click',()=>{offset+=50;list();});}
  function fieldMarkup(f){const v=state.content.draft[f.key]||'';if(f.type==='image')return `<div class="field"><label>${esc(f.label)}</label><div class="image-field ${f.key==='logo'?'logo':''}"><img src="${esc(v)}" alt="${esc(f.label)}"><div class="upload-row"><span>JPG, PNG, WebP · maks. 4 MB</span><input type="file" accept="image/jpeg,image/png,image/webp" aria-label="Unggah ${esc(f.label)}" data-upload="${f.key}"></div></div></div>`;return `<div class="field"><label for="field-${f.key}">${esc(f.label)}</label>${f.type==='textarea'?`<textarea id="field-${f.key}" data-field="${f.key}" maxlength="${f.max}" rows="4">${esc(v)}</textarea>`:`<input id="field-${f.key}" data-field="${f.key}" maxlength="${f.max}" value="${esc(v)}" ${f.key==='email'?'type="email"':f.key==='whatsapp'?'type="tel"':''}>`}</div>`;}
  function editor(){const o=state.order;return `<div class="editor-grid"><section class="editor-panel card"><nav class="editor-tabs" role="tablist" aria-label="Bagian website">${state.fields.map((g,i)=>`<button type="button" role="tab" aria-selected="${group===i}" data-group="${i}">${g.label}</button>`).join('')}</nav><form class="fields" id="content-form" role="tabpanel" aria-label="${esc(state.fields[group].label)}">${state.fields[group].items.map(fieldMarkup).join('')}</form><div class="editor-foot"><span data-save-state>${dirty?'Ada perubahan belum disimpan':`Draft tersimpan · revisi ${state.content.revision}`}</span><div class="actions"><button class="btn primary" data-save>${svg('save')} Simpan perubahan</button><button class="btn" data-publish ${o.isPreview?'hidden':''} ${mode==='client'&&o.status!=='active'?'disabled':''}>${svg('publish')} ${mode==='admin'?'Terbitkan website':'Terbitkan perubahan'}</button></div></div></section><aside class="preview card"><div class="preview-head"><span>Pratinjau website</span><a href="/preview/${o.slug}" target="_blank" rel="noopener">Buka penuh</a></div><iframe title="Pratinjau ${esc(o.businessName)}" src="/preview/${o.slug}?rev=${state.content.revision}" loading="lazy"></iframe></aside></div>`;}
  function busyEditor(busy){app.querySelectorAll('.editor-grid input,.editor-grid textarea,.editor-grid button').forEach(e=>{if(busy){e.dataset.wasDisabled=String(e.disabled);e.disabled=true;}else{e.disabled=e.dataset.wasDisabled==='true';delete e.dataset.wasDisabled;}});}
  function bindEditor(){app.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{group=Number(b.dataset.group);app.querySelector('.editor-grid').outerHTML=editor();bindEditor();});app.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('input',()=>{state.content.draft[input.dataset.field]=input.value;dirty=true;app.querySelector('[data-save-state]').textContent='Ada perubahan belum disimpan';}));app.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const f=input.files[0];if(!f||saving||uploading||publishing)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>4*1024*1024){notify('Gunakan JPG, PNG, atau WebP maksimal 4 MB.',true);input.value='';return;}uploading=true;busyEditor(true);try{const r=await api(endpoint('media'),{method:'POST',body:f,headers:{'Content-Type':f.type}});state.content.draft[input.dataset.upload]=r.url;input.closest('.image-field').querySelector('img').src=r.url;dirty=true;app.querySelector('[data-save-state]').textContent='Ada perubahan belum disimpan';notify('Gambar diunggah. Simpan perubahan untuk memakai gambar ini.');}catch(e){notify(e.message,true);}finally{uploading=false;busyEditor(false);input.value='';}});app.querySelector('[data-save]').onclick=save;app.querySelector('[data-publish]').onclick=async()=>{if(saving||uploading||publishing)return;if(dirty){notify('Simpan perubahan sebelum menerbitkan.',true);return;}if(!await confirmAction('Terbitkan perubahan website?','Konten yang tersimpan akan terlihat oleh pengunjung website.','Terbitkan'))return;publishing=true;busyEditor(true);try{const r=await api(endpoint('publish'),{method:'POST',body:{revision:state.content.revision}});state.content.publishedRevision=r.publishedRevision;state.order.status='active';state.order.statusLabel='Website aktif';notify('Website berhasil diterbitkan.');await load();}catch(e){notify(e.message,true);}finally{publishing=false;busyEditor(false);}};app.querySelector('#content-form').onsubmit=e=>{e.preventDefault();save();};}
  const endpoint=action=>mode==='admin'?`/api/admin/orders/${state.order.id}/${action}`:`/api/client/${action}`;
  async function save(){if(saving||uploading||publishing)return;saving=true;busyEditor(true);const button=app.querySelector('[data-save]');button.disabled=true;button.textContent='Menyimpan…';try{const r=await api(endpoint('content'),{method:'PUT',body:{content:state.content.draft,revision:state.content.revision}});state.content.draft=r.content;state.content.revision=r.revision;dirty=false;app.querySelector('[data-save-state]').textContent=`Draft tersimpan · revisi ${r.revision}`;const frame=app.querySelector('.preview iframe');if(frame)frame.src=`/preview/${state.order.slug}?rev=${r.revision}`;notify('Perubahan tersimpan.');}catch(e){notify(e.message,true);}finally{saving=false;busyEditor(false);button.disabled=false;button.innerHTML=svg('save')+' Simpan perubahan';}}
  function client(){const o=state.order,active=o.status==='active'&&!o.isPreview,canEdit=Boolean(state.content);layout(`<div class="topline"><div><h1>${esc(o.businessName)}</h1><p class="muted">${o.isPreview?'Percobaan CMS':esc(o.reference)+' · Rasio Profile'}</p></div><div class="actions">${canEdit?`<a class="btn" href="/preview/${o.slug}" target="_blank" rel="noopener">${svg('preview')} Pratinjau</a>`:''}${active?`<a class="btn" href="/website/${o.slug}" target="_blank" rel="noopener">Buka website</a>`:''}</div></div><div class="order-banner card"><div><strong>${esc(o.statusLabel)}</strong><p>${o.isPreview?'Ubah konten, simpan, lalu lihat hasilnya melalui pratinjau.':o.paymentStatus==='verified'?'Pembayaran terverifikasi.':`Total paket ${rupiah(o.total)} untuk ${o.duration} bulan. Tim Rasio akan menghubungi Anda untuk pembayaran.`}</p></div><div class="actions">${statusPill(o)}<a class="btn green" href="https://wa.me/60142317052?text=${encodeURIComponent(`Halo Rasio, saya ingin membahas pesanan ${o.reference}.`)}" target="_blank" rel="noopener">${svg('wa')} Hubungi Rasio</a></div></div>${canEdit?editor():`<section class="waiting card"><span class="icon">${svg('orders')}</span><h2>Pesanan Anda sudah diterima</h2><p>Tim Rasio akan menghubungi Anda dalam 1 × 24 jam untuk melanjutkan pembayaran dan setup website.</p><div class="details-grid"><div><span>Domain pilihan</span><strong>${esc(o.domain)}</strong></div><div><span>Durasi layanan</span><strong>${o.duration} bulan</strong></div></div></section>`}`);if(canEdit)bindEditor();}
  function adminDetail(){const o=state.order;layout(`<a class="link-back" href="/admin">← Semua pesanan</a><div class="topline"><div><h1>${esc(o.businessName)}</h1><p class="muted">${esc(o.reference)} · ${date(o.createdAt)}</p></div><div class="actions"><a class="btn" href="/preview/${o.slug}" target="_blank" rel="noopener">${svg('preview')} Pratinjau</a>${o.status==='active'?`<a class="btn" href="/website/${o.slug}" target="_blank" rel="noopener">Buka website</a>`:''}</div></div><div class="order-details"><section class="card"><h2>Rincian pesanan</h2><div class="details-grid">${[['Penanggung jawab',o.customerName],['WhatsApp',o.whatsapp],['Email kontak',o.email||'—'],['Domain pilihan',o.domain],['Langganan',`${o.duration} bulan`],['Total paket',rupiah(o.total)],['Tarif perpanjangan',`${rupiah(o.renewalMonthly)}/bulan`],['Pembayaran',o.paymentStatus==='verified'?'Terverifikasi':'Menunggu pembayaran']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="actions" style="margin-top:24px"><a class="btn green" href="https://wa.me/${o.whatsapp.replace(/\D/g,'')}" target="_blank" rel="noopener">${svg('wa')} Hubungi klien</a><button class="btn" data-invite>Buat tautan akses CMS</button><button class="btn danger" data-revoke>Cabut akses klien</button></div><div class="invite-box" hidden data-invite-box><p>Tautan berlaku 7 hari dan dapat dipakai satu kali. Kirim hanya kepada pemilik website.</p><input aria-label="Tautan akses CMS" readonly data-invite-url><button class="btn" data-copy>Salin tautan</button></div></section><section class="card"><h2>Proses pengerjaan</h2><form class="admin-form"><div class="field"><label for="order-status">Status pesanan</label><select id="order-status">${[['new','Pesanan baru'],['materials','Menunggu materi'],['building','Sedang disiapkan'],['review','Siap ditinjau'],...(o.status==='active'?[['active','Website aktif']]:[]),['cancelled','Dibatalkan']].map(([v,l])=>`<option value="${v}" ${o.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="domain-status">Pengaturan domain</label><select id="domain-status"><option value="pending" ${o.domainStatus==='pending'?'selected':''}>Belum dikonfirmasi</option><option value="confirmed" ${o.domainStatus==='confirmed'?'selected':''}>Sudah dikonfirmasi Rasio</option></select></div><div class="field"><label for="payment-status">Pembayaran</label><select id="payment-status"><option value="pending" ${o.paymentStatus!=='verified'?'selected':''}>Menunggu pembayaran</option><option value="verified" ${o.paymentStatus==='verified'?'selected':''}>Sudah saya verifikasi</option></select></div><div class="field"><label for="payment-reference">Referensi pembayaran</label><input id="payment-reference" value="${esc(o.paymentReference)}" placeholder="Nomor transaksi / referensi transfer" maxlength="200"></div><div class="field"><label for="order-notes">Catatan internal</label><textarea id="order-notes" maxlength="3000">${esc(o.notes)}</textarea></div><button class="btn primary">Simpan status</button></form></section></div><div class="admin-edit-title"><h2>Konten website</h2><span class="pill">${state.content.publishedRevision?`Terbit · revisi ${state.content.publishedRevision}`:'Belum terbit'}</span></div>${editor()}<section class="activity card"><h2>Aktivitas pesanan</h2><ul>${state.audit.map(a=>`<li><span>${esc(a.detail)}</span><time>${date(a.created_at)}</time></li>`).join('')}</ul></section>`);bindEditor();app.querySelector('.admin-form').onsubmit=async e=>{e.preventDefault();const pay=app.querySelector('#payment-status').value;if(pay==='verified'&&o.paymentStatus!=='verified'&&!await confirmAction('Verifikasi pembayaran?','Pastikan dana sudah diterima dan referensi transaksi sudah Anda periksa.','Sudah diperiksa'))return;const btn=e.target.querySelector('button');btn.disabled=true;try{await api(`/api/admin/orders/${o.id}`,{method:'PATCH',body:{status:app.querySelector('#order-status').value,paymentStatus:pay,paymentReference:app.querySelector('#payment-reference').value,domainStatus:app.querySelector('#domain-status').value,notes:app.querySelector('#order-notes').value}});const fresh=await api(`/api/admin/orders/${o.id}`);const draft=state.content;state=fresh;state.content=draft;notify('Status pesanan tersimpan.');adminDetail();}catch(e){notify(e.message,true);btn.disabled=false;}};app.querySelector('[data-invite]').onclick=async()=>{try{const r=await api(`/api/admin/orders/${o.id}/invite`,{method:'POST',body:{}});app.querySelector('[data-invite-box]').hidden=false;app.querySelector('[data-invite-url]').value=r.url;}catch(e){notify(e.message,true);}};app.querySelector('[data-copy]').onclick=async()=>{const input=app.querySelector('[data-invite-url]');try{await navigator.clipboard.writeText(input.value);notify('Tautan akses disalin.');}catch{input.select();notify('Pilih dan salin tautan akses.');}};app.querySelector('[data-revoke]').onclick=async()=>{if(!await confirmAction('Cabut akses klien?','Sesi dan tautan akses lama tidak dapat digunakan lagi. Anda bisa membuat tautan baru.','Cabut akses'))return;try{await api(`/api/admin/orders/${o.id}/revoke`,{method:'POST',body:{}});app.querySelector('[data-invite-box]').hidden=true;notify('Akses klien dicabut.');}catch(e){notify(e.message,true);}};}
  async function load(){if(mode==='admin'){const id=new URLSearchParams(location.search).get('order');if(validOrder(id)){state=await api(`/api/admin/orders/${id}`);adminDetail();}else await list();}else{state=await api('/api/client/order');client();}}
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  (async()=>{const code=new URLSearchParams(location.hash.slice(1)).get('akses');if(code){history.replaceState(null,'',location.pathname+location.search);try{session=await api('/api/access',{method:'POST',body:{code}});}catch(e){login(e.message);return;}}else{try{session=await api('/api/session');}catch(e){if(e.status===401){login();return;}app.innerHTML='<div class="loading">Dashboard belum dapat dimuat. <a class="btn" href="'+location.pathname+'">Coba lagi</a></div>';notify(e.message,true);return;}}try{if(!routeSession(session))return;await load();}catch(e){notify(e.message,true);app.innerHTML='<div class="loading">Data belum dapat dimuat. <a class="btn" href="'+location.pathname+'">Coba lagi</a></div>';}})();
})();
